#!/usr/bin/env bash
# File generated by ChatGPT based on CCA2 setup secret file, I did not know how to generate an .sh file myself
set -euo pipefail

# Check if secret already in namespace 
EXISTING_SECRET=$(kubectl get secret road-session-secret \
  --namespace=default \
  --ignore-not-found \
  -o name)

# If has existing key, keeps it the same 
if [[ -n "$EXISTING_SECRET" ]]; then
  echo "Session Secret already exists; keeping its current key."
  exit 0
fi

# No curr key, creates a new one 
SESSION_KEY=$(python3 -c "import secrets; print(secrets.token_hex(32))")

# Create it as kubernetes secret and let know that it was created
kubectl create secret generic road-session-secret \
  --namespace=default \
  --from-literal=SECRET_KEY="$SESSION_KEY"

unset SESSION_KEY

echo "Session Secret created."

